 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def components(color):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p = (x + dx, y + dy)
                        if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == color and p not in seen:
                            seen.add(p)
                            stack.append(p)
                r0 = min(x for x, y in cells)
                c0 = min(y for x, y in cells)
                shape = frozenset((x - r0, y - c0) for x, y in cells)
                result.append((cells, shape))
        return result

    references = {}
    for color in range(2, 10):
        for _, shape in components(color):
            references.setdefault(shape, color)

    out = [row[:] for row in grid]
    for cells, shape in components(1):
        if shape in references:
            color = references[shape]
            for r, c in cells:
                out[r][c] = color
    return out

if __name__ == '__main__':
